import { escapeHtml } from "./ui.js";
export const metricRow = metric => `<div class="metric-line"><div><strong>${escapeHtml(metric.name)}</strong><small>${metric.reportName&&metric.reportName!==metric.name?`FitMao: ${escapeHtml(metric.reportName)} · `:""}Reference: ${escapeHtml(metric.range)}</small></div><span>${escapeHtml(metric.value)} ${escapeHtml(metric.unit)}</span><span class="status status-${String(metric.status).toLowerCase().replaceAll(" ","-")}">Report says ${escapeHtml(metric.status)}</span></div>`;
